create table if not exists public.workouts (id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,performed_on date not null,title text not null,notes text not null default '',entries jsonb not null default '[]'::jsonb,created_at timestamptz not null default now(),constraint workout_entries_array check(jsonb_typeof(entries)='array'));
create table if not exists public.plans (id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,name text not null,exercises jsonb not null default '[]'::jsonb,created_at timestamptz not null default now(),constraint plan_exercises_array check(jsonb_typeof(exercises)='array'));
create table if not exists public.body_metrics (id uuid primary key,user_id uuid not null references auth.users(id) on delete cascade,measured_on date not null,weight_kg numeric(6,2),body_fat_pct numeric(5,2),waist_cm numeric(6,2),notes text not null default '',created_at timestamptz not null default now(),constraint weight_bounds check(weight_kg is null or weight_kg between 0 and 500),constraint bodyfat_bounds check(body_fat_pct is null or body_fat_pct between 0 and 100),constraint waist_bounds check(waist_cm is null or waist_cm between 0 and 500));
create index if not exists workouts_user_date on public.workouts(user_id,performed_on desc);
create index if not exists body_user_date on public.body_metrics(user_id,measured_on desc);
alter table public.workouts enable row level security;alter table public.plans enable row level security;alter table public.body_metrics enable row level security;
do $$ declare tbl text; begin foreach tbl in array array['workouts','plans','body_metrics'] loop execute format('drop policy if exists own_records on public.%I',tbl);execute format('create policy own_records on public.%I for all to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id)',tbl);end loop;end $$;
revoke all on public.workouts,public.plans,public.body_metrics from anon;grant select,insert,update,delete on public.workouts,public.plans,public.body_metrics to authenticated;
